/**
 * 时间工具模块
 * 提供日期格式化、倒计时计算等功能
 */

/**
 * 获取当前时间（支持调试覆盖）
 * @param {Date} debugNow 调试用时间
 * @returns {Date}
 */
export function getNow(debugNow) {
  return debugNow || new Date()
}

/**
 * 格式化时间为 HH:MM
 * @param {Date} date
 * @returns {string}
 */
export function formatTime(date) {
  const hours = String(date.getHours()).padStart(2, '0')
  const minutes = String(date.getMinutes()).padStart(2, '0')
  return `${hours}:${minutes}`
}

/**
 * 格式化日期为 M月D日
 * @param {Date} date
 * @returns {string}
 */
export function formatDate(date) {
  const month = date.getMonth() + 1
  const day = date.getDate()
  return `${month}月${day}日`
}

/**
 * 获取星期几（中文）
 * @param {Date} date
 * @returns {string}
 */
export function getWeekday(date) {
  const days = ['周日', '周一', '周二', '周三', '周四', '周五', '周六']
  return days[date.getDay()]
}

/**
 * 格式化完整日期：8月18日 · 周二
 * @param {Date} date
 * @returns {string}
 */
export function formatFullDate(date) {
  return `${formatDate(date)} · ${getWeekday(date)}`
}

/**
 * 解析时间字符串为当天的 Date 对象
 * @param {string} timeStr 格式：HH:MM
 * @param {Date} baseDate 基准日期
 * @returns {Date}
 */
export function parseTimeToDate(timeStr, baseDate) {
  const [hours, minutes] = timeStr.split(':').map(Number)
  const date = new Date(baseDate)
  date.setHours(hours, minutes, 0, 0)
  return date
}

/**
 * 解析日期时间字符串
 * @param {string} dateTimeStr 格式：YYYY-MM-DDTHH:MM:SS
 * @returns {Date}
 */
export function parseDateTime(dateTimeStr) {
  return new Date(dateTimeStr)
}

/**
 * 计算两个时间之间的分钟差
 * @param {Date} start
 * @param {Date} end
 * @returns {number}
 */
export function diffMinutes(start, end) {
  return Math.floor((end - start) / (1000 * 60))
}

/**
 * 计算两个时间之间的秒数差
 * @param {Date} start
 * @param {Date} end
 * @returns {number}
 */
export function diffSeconds(start, end) {
  return Math.floor((end - start) / 1000)
}

/**
 * 格式化剩余时间（分钟）
 * @param {number} minutes
 * @returns {string}
 */
export function formatRemainingMinutes(minutes) {
  if (minutes < 1) return '不足1分钟'
  if (minutes < 60) return `${minutes}分钟`
  const hours = Math.floor(minutes / 60)
  const mins = minutes % 60
  if (mins === 0) return `${hours}小时`
  return `${hours}小时${mins}分钟`
}

/**
 * 格式化倒计时（考试用）
 * @param {Date} targetDate
 * @param {Date} now
 * @returns {object} { value, unit }
 */
export function formatCountdown(targetDate, now) {
  const diffMs = targetDate - now
  if (diffMs <= 0) return { value: 0, unit: '已结束', isFinished: true }

  const diffHours = Math.floor(diffMs / (1000 * 60 * 60))
  const diffDays = Math.floor(diffHours / 24)

  if (diffDays > 0) {
    return { value: diffDays, unit: '天', isFinished: false }
  }
  if (diffHours > 0) {
    return { value: diffHours, unit: '小时', isFinished: false }
  }

  const diffMins = Math.floor(diffMs / (1000 * 60))
  return { value: diffMins, unit: '分钟', isFinished: false }
}

/**
 * 格式化考试倒计时（精确到秒）
 * @param {Date} targetDate
 * @param {Date} now
 * @returns {string}
 */
export function formatExamCountdown(targetDate, now) {
  const diffMs = targetDate - now
  if (diffMs <= 0) return '已结束'

  const totalSeconds = Math.floor(diffMs / 1000)
  const hours = Math.floor(totalSeconds / 3600)
  const minutes = Math.floor((totalSeconds % 3600) / 60)
  const seconds = totalSeconds % 60

  return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`
}

/**
 * 获取星期数字（1-7，1是周一）
 * @param {Date} date
 * @returns {number}
 */
export function getWeekdayNumber(date) {
  const day = date.getDay()
  return day === 0 ? 7 : day
}

/**
 * 判断是否是今天
 * @param {Date} date
 * @param {Date} now
 * @returns {boolean}
 */
export function isToday(date, now) {
  return date.getFullYear() === now.getFullYear() &&
    date.getMonth() === now.getMonth() &&
    date.getDate() === now.getDate()
}

/**
 * 获取今天的开始时间
 * @param {Date} now
 * @returns {Date}
 */
export function getTodayStart(now) {
  const start = new Date(now)
  start.setHours(0, 0, 0, 0)
  return start
}

/**
 * 获取今天的结束时间
 * @param {Date} now
 * @returns {Date}
 */
export function getTodayEnd(now) {
  const end = new Date(now)
  end.setHours(23, 59, 59, 999)
  return end
}

/**
 * 课程逻辑模块
 * 提供课程筛选、当前课程判断、下一课程查找等功能
 */

import { courses } from './data'
import { getNow, parseTimeToDate, diffMinutes, getWeekdayNumber, formatRemainingMinutes } from './time'

/**
 * 获取今天的课程列表
 * @param {Date} now 当前时间
 * @param {number} currentWeek 当前教学周（默认1）
 * @returns {Array}
 */
export function getTodayCourses(now, currentWeek = 1) {
  const weekday = getWeekdayNumber(now)
  return courses
    .filter(c => c.weekday === weekday && c.weeks.includes(currentWeek))
    .sort((a, b) => a.startTime.localeCompare(b.startTime))
}

/**
 * 获取指定星期的课程
 * @param {number} weekday 星期几（1-7）
 * @param {number} currentWeek 当前教学周
 * @returns {Array}
 */
export function getCoursesByWeekday(weekday, currentWeek = 1) {
  return courses
    .filter(c => c.weekday === weekday && c.weeks.includes(currentWeek))
    .sort((a, b) => a.startTime.localeCompare(b.startTime))
}

/**
 * 获取本周所有课程
 * @param {number} currentWeek 当前教学周
 * @returns {object} 按星期分组的课程
 */
export function getWeekCourses(currentWeek = 1) {
  const weekCourses = {}
  for (let i = 1; i <= 7; i++) {
    weekCourses[i] = getCoursesByWeekday(i, currentWeek)
  }
  return weekCourses
}

/**
 * 获取当前正在进行的课程
 * @param {Date} now
 * @param {number} currentWeek
 * @returns {object|null}
 */
export function getCurrentCourse(now, currentWeek = 1) {
  const todayCourses = getTodayCourses(now, currentWeek)
  for (const course of todayCourses) {
    const startTime = parseTimeToDate(course.startTime, now)
    const endTime = parseTimeToDate(course.endTime, now)
    if (now >= startTime && now < endTime) {
      return course
    }
  }
  return null
}

/**
 * 获取下一节课（今天内）
 * @param {Date} now
 * @param {number} currentWeek
 * @returns {object|null}
 */
export function getNextCourse(now, currentWeek = 1) {
  const todayCourses = getTodayCourses(now, currentWeek)
  for (const course of todayCourses) {
    const startTime = parseTimeToDate(course.startTime, now)
    if (startTime > now) {
      return course
    }
  }
  return null
}

/**
 * 跨天查找下一节课
 * @param {Date} now
 * @param {number} currentWeek
 * @returns {object|null} { course, daysLater, date }
 */
export function getNextCourseAcrossDays(now, currentWeek = 1) {
  // 先检查今天剩余课程
  const nextToday = getNextCourse(now, currentWeek)
  if (nextToday) {
    return { course: nextToday, daysLater: 0, date: now }
  }

  // 检查未来7天
  for (let i = 1; i <= 7; i++) {
    const futureDate = new Date(now)
    futureDate.setDate(futureDate.getDate() + i)
    const weekday = getWeekdayNumber(futureDate)
    const courses = getCoursesByWeekday(weekday, currentWeek)
    if (courses.length > 0) {
      return { course: courses[0], daysLater: i, date: futureDate }
    }
  }
  return null
}

/**
 * 获取课程进度（0-1）
 * @param {object} course
 * @param {Date} now
 * @returns {number}
 */
export function getCourseProgress(course, now) {
  const startTime = parseTimeToDate(course.startTime, now)
  const endTime = parseTimeToDate(course.endTime, now)
  const total = endTime - startTime
  const elapsed = now - startTime
  const progress = elapsed / total
  return Math.max(0, Math.min(1, progress))
}

/**
 * 获取课程剩余时间（分钟）
 * @param {object} course
 * @param {Date} now
 * @returns {number}
 */
export function getCourseRemainingTime(course, now) {
  const endTime = parseTimeToDate(course.endTime, now)
  return Math.max(0, diffMinutes(now, endTime))
}

/**
 * 获取课程状态
 * @param {object} course
 * @param {Date} now
 * @returns {string} 'finished' | 'ongoing' | 'upcoming'
 */
export function getCourseStatus(course, now) {
  const startTime = parseTimeToDate(course.startTime, now)
  const endTime = parseTimeToDate(course.endTime, now)
  if (now >= endTime) return 'finished'
  if (now >= startTime) return 'ongoing'
  return 'upcoming'
}

/**
 * 获取距离开始的分钟数
 * @param {object} course
 * @param {Date} now
 * @returns {number}
 */
export function getMinutesUntilStart(course, now) {
  const startTime = parseTimeToDate(course.startTime, now)
  return Math.max(0, diffMinutes(now, startTime))
}

/**
 * 格式化课程开始状态文字
 * @param {object} course
 * @param {Date} now
 * @returns {string}
 */
export function formatCourseStartStatus(course, now) {
  const minutes = getMinutesUntilStart(course, now)
  if (minutes === 0) return '即将开始'
  return `还有 ${minutes} 分钟`
}

/**
 * 判断今日课程是否全部结束
 * @param {Date} now
 * @param {number} currentWeek
 * @returns {boolean}
 */
export function isTodayCoursesFinished(now, currentWeek = 1) {
  const todayCourses = getTodayCourses(now, currentWeek)
  if (todayCourses.length === 0) return true
  return todayCourses.every(c => getCourseStatus(c, now) === 'finished')
}

/**
 * 本地存储模块
 * 使用 @system.storage 实现离线数据持久化
 */

import { courses, exams, tasks } from './data'

const STORAGE_KEYS = {
  COURSES: 'campus_courses',
  EXAMS: 'campus_exams',
  TASKS: 'campus_tasks',
  SETTINGS: 'campus_settings'
}

/**
 * 初始化存储（首次启动时写入 Mock 数据）
 */
export function initStorage() {
  try {
    // 检查是否已有数据
    const storedCourses = localStorage.getItem(STORAGE_KEYS.COURSES)
    if (!storedCourses) {
      // 首次启动，写入 Mock 数据
      localStorage.setItem(STORAGE_KEYS.COURSES, JSON.stringify(courses))
      localStorage.setItem(STORAGE_KEYS.EXAMS, JSON.stringify(exams))
      localStorage.setItem(STORAGE_KEYS.TASKS, JSON.stringify(tasks))
      console.log('Storage initialized with mock data')
    } else {
      console.log('Storage already initialized')
    }
  } catch (e) {
    console.error('Failed to init storage:', e)
  }
}

/**
 * 获取课程数据
 * @returns {Array}
 */
export function getCourses() {
  try {
    const data = localStorage.getItem(STORAGE_KEYS.COURSES)
    return data ? JSON.parse(data) : courses
  } catch (e) {
    console.error('Failed to get courses:', e)
    return courses
  }
}

/**
 * 获取考试数据
 * @returns {Array}
 */
export function getExams() {
  try {
    const data = localStorage.getItem(STORAGE_KEYS.EXAMS)
    return data ? JSON.parse(data) : exams
  } catch (e) {
    console.error('Failed to get exams:', e)
    return exams
  }
}

/**
 * 获取待办数据
 * @returns {Array}
 */
export function getTasks() {
  try {
    const data = localStorage.getItem(STORAGE_KEYS.TASKS)
    return data ? JSON.parse(data) : tasks
  } catch (e) {
    console.error('Failed to get tasks:', e)
    return tasks
  }
}

/**
 * 更新任务状态
 * @param {string} taskId
 * @param {boolean} finished
 */
export function updateTaskStatus(taskId, finished) {
  try {
    const tasks = getTasks()
    const index = tasks.findIndex(t => t.id === taskId)
    if (index !== -1) {
      tasks[index].finished = finished
      localStorage.setItem(STORAGE_KEYS.TASKS, JSON.stringify(tasks))
    }
  } catch (e) {
    console.error('Failed to update task:', e)
  }
}

/**
 * 重置为 Mock 数据（调试用）
 */
export function resetToMockData() {
  try {
    localStorage.setItem(STORAGE_KEYS.COURSES, JSON.stringify(courses))
    localStorage.setItem(STORAGE_KEYS.EXAMS, JSON.stringify(exams))
    localStorage.setItem(STORAGE_KEYS.TASKS, JSON.stringify(tasks))
    console.log('Storage reset to mock data')
  } catch (e) {
    console.error('Failed to reset storage:', e)
  }
}

/**
 * 考试逻辑模块
 * 提供考试筛选、倒计时计算等功能
 */

import { getExams } from './storage'
import { formatCountdown, formatExamCountdown, parseDateTime, getNow } from './time'

/**
 * 获取最近的考试
 * @param {Date} now
 * @returns {object|null}
 */
export function getNearestExam(now) {
  const exams = getExams()
  const upcomingExams = exams
    .filter(e => parseDateTime(`${e.date}T${e.startTime}:00`) > now)
    .sort((a, b) => {
      const dateA = parseDateTime(`${a.date}T${a.startTime}:00`)
      const dateB = parseDateTime(`${b.date}T${b.startTime}:00`)
      return dateA - dateB
    })
  return upcomingExams.length > 0 ? upcomingExams[0] : null
}

/**
 * 获取所有即将到来的考试
 * @param {Date} now
 * @returns {Array}
 */
export function getUpcomingExams(now) {
  const exams = getExams()
  return exams
    .filter(e => parseDateTime(`${e.date}T${e.startTime}:00`) > now)
    .sort((a, b) => {
      const dateA = parseDateTime(`${a.date}T${a.startTime}:00`)
      const dateB = parseDateTime(`${b.date}T${b.startTime}:00`)
      return dateA - dateB
    })
}

/**
 * 获取考试倒计时
 * @param {object} exam
 * @param {Date} now
 * @returns {object} { value, unit }
 */
export function getExamCountdown(exam, now) {
  const examDate = parseDateTime(`${exam.date}T${exam.startTime}:00`)
  return formatCountdown(examDate, now)
}

/**
 * 获取考试精确倒计时（用于非常临近的情况）
 * @param {object} exam
 * @param {Date} now
 * @returns {string}
 */
export function getExamPreciseCountdown(exam, now) {
  const examDate = parseDateTime(`${exam.date}T${exam.startTime}:00`)
  return formatExamCountdown(examDate, now)
}

/**
 * 获取考试日期格式化
 * @param {object} exam
 * @returns {string} 如：8月21日 · 09:00
 */
export function formatExamDate(exam) {
  const date = parseDateTime(`${exam.date}T00:00:00`)
  const month = date.getMonth() + 1
  const day = date.getDate()
  return `${month}月${day}日 · ${exam.startTime}`
}

/**
 * 获取考试状态
 * @param {object} exam
 * @param {Date} now
 * @returns {string} 'upcoming' | 'today' | 'finished'
 */
export function getExamStatus(exam, now) {
  const examDate = parseDateTime(`${exam.date}T${exam.startTime}:00`)
  const examEnd = parseDateTime(`${exam.date}T${exam.endTime}:00`)

  if (now >= examEnd) return 'finished'
  if (now >= examDate) return 'ongoing'

  // 判断是否是今天
  const examDay = new Date(exam.date)
  if (examDay.toDateString() === now.toDateString()) return 'today'

  return 'upcoming'
}

/**
 * 获取考试数量摘要
 * @param {Date} now
 * @returns {object} { count, nearestCourse, daysUntil }
 */
export function getExamSummary(now) {
  const nearest = getNearestExam(now)
  if (!nearest) {
    return { count: 0, nearestCourse: null, daysUntil: null }
  }

  const countdown = getExamCountdown(nearest, now)
  return {
    count: getUpcomingExams(now).length,
    nearestCourse: nearest.course,
    daysUntil: countdown
  }
}

/**
 * 待办逻辑模块
 * 提供待办筛选、分类、倒计时等功能
 */

import { getTasks, updateTaskStatus } from './storage'
import { parseDateTime, diffMinutes, getNow, isToday } from './time'

/**
 * 获取今日待办
 * @param {Date} now
 * @returns {Array}
 */
export function getTodayTasks(now) {
  const tasks = getTasks()
  return tasks.filter(t => {
    if (t.finished) return false
    const deadline = parseDateTime(t.deadline)
    return isToday(deadline, now)
  }).sort((a, b) => parseDateTime(a.deadline) - parseDateTime(b.deadline))
}

/**
 * 获取本周待办
 * @param {Date} now
 * @returns {Array}
 */
export function getWeekTasks(now) {
  const tasks = getTasks()
  const weekEnd = new Date(now)
  weekEnd.setDate(weekEnd.getDate() + (7 - weekEnd.getDay()))
  weekEnd.setHours(23, 59, 59, 999)

  return tasks.filter(t => {
    if (t.finished) return false
    const deadline = parseDateTime(t.deadline)
    return deadline > now && deadline <= weekEnd && !isToday(deadline, now)
  }).sort((a, b) => parseDateTime(a.deadline) - parseDateTime(b.deadline))
}

/**
 * 获取未来待办
 * @param {Date} now
 * @returns {Array}
 */
export function getFutureTasks(now) {
  const tasks = getTasks()
  const weekEnd = new Date(now)
  weekEnd.setDate(weekEnd.getDate() + (7 - weekEnd.getDay()))
  weekEnd.setHours(23, 59, 59, 999)

  return tasks.filter(t => {
    if (t.finished) return false
    const deadline = parseDateTime(t.deadline)
    return deadline > weekEnd
  }).sort((a, b) => parseDateTime(a.deadline) - parseDateTime(b.deadline))
}

/**
 * 获取已完成待办
 * @returns {Array}
 */
export function getFinishedTasks() {
  const tasks = getTasks()
  return tasks.filter(t => t.finished)
}

/**
 * 获取待办剩余时间
 * @param {object} task
 * @param {Date} now
 * @returns {object} { value, unit, isUrgent, isCritical }
 */
export function getTaskCountdown(task, now) {
  const deadline = parseDateTime(task.deadline)
  const remaining = deadline - now

  if (remaining <= 0) {
    return { value: 0, unit: '已截止', isUrgent: false, isCritical: true }
  }

  const minutes = Math.floor(remaining / (1000 * 60))
  const hours = Math.floor(minutes / 60)
  const days = Math.floor(hours / 24)

  // 判断紧急程度
  const isCritical = hours < 1
  const isUrgent = hours < 6

  if (days > 0) {
    return { value: days, unit: '天', isUrgent, isCritical }
  }
  if (hours > 0) {
    return { value: hours, unit: '小时', isUrgent, isCritical }
  }
  return { value: minutes, unit: '分钟', isUrgent, isCritical }
}

/**
 * 格式化待办倒计时文字
 * @param {object} task
 * @param {Date} now
 * @returns {string}
 */
export function formatTaskCountdown(task, now) {
  const countdown = getTaskCountdown(task, now)
  if (countdown.unit === '已截止') return '已截止'
  return `还有 ${countdown.value} ${countdown.unit}`
}

/**
 * 获取待办摘要
 * @param {Date} now
 * @returns {object} { todayCount, urgentCount }
 */
export function getTaskSummary(now) {
  const todayTasks = getTodayTasks(now)
  const allTasks = getTasks().filter(t => !t.finished)
  const urgentCount = allTasks.filter(t => {
    const countdown = getTaskCountdown(t, now)
    return countdown.isUrgent
  }).length

  return {
    todayCount: todayTasks.length,
    urgentCount
  }
}

/**
 * 切换任务完成状态
 * @param {string} taskId
 * @returns {boolean} 新状态
 */
export function toggleTaskStatus(taskId) {
  const tasks = getTasks()
  const task = tasks.find(t => t.id === taskId)
  if (task) {
    const newStatus = !task.finished
    updateTaskStatus(taskId, newStatus)
    return newStatus
  }
  return false
}

/**
 * 获取待办类型文字
 * @param {string} type
 * @returns {string}
 */
export function getTaskTypeText(type) {
  const typeMap = {
    experiment: '实验',
    homework: '作业',
    report: '报告',
    other: '其他'
  }
  return typeMap[type] || '其他'
}

