const DEBUG_NOW = null

export default {
  protected: {
    courseId: ''
  },

  private: {
    course: null,
    status: 'upcoming',
    progress: 0,
    progressPercent: 0,
    remainingMinutes: 0,
    minutesUntilStart: 0,
    startX: 0,
    startY: 0,
    gestureTriggered: false
  },

  onInit() {
    this.loadCourse()
  },

  loadCourse() {
    const now = getNow(DEBUG_NOW)

    // 查找课程
    this.course = courses.find(c => c.id === this.courseId)

    if (this.course) {
      this.status = getCourseStatus(this.course, now)

      if (this.status === 'ongoing') {
        this.progress = Math.round(getCourseProgress(this.course, now) * 100)
        this.progressPercent = this.progress
        this.remainingMinutes = getCourseRemainingTime(this.course, now)
      } else if (this.status === 'upcoming') {
        this.minutesUntilStart = getMinutesUntilStart(this.course, now)
      }
    }
  },

  onTouchStart(e) {
    this.startX = e.clientX
    this.startY = e.clientY
    this.gestureTriggered = false
  },

  onTouchMove(e) {
    if (this.gestureTriggered) return
    if (this.startX > 50) return

    const deltaX = e.clientX - this.startX
    const deltaY = e.clientY - this.startY

    if (deltaX >= 80 && deltaX > Math.abs(deltaY) * 1.2) {
      this.gestureTriggered = true
      router.back()
    }
  },

  onTouchEnd() {
    this.gestureTriggered = false
  },

  goBack() {
    router.back()
  }
}

